#!/usr/bin/env python3
"""Check README.md, README.fr.md, CONTRIBUTING.md and SECURITY.md against the readme-forge rules.

Usage: python3 lint_readme.py [PROJECT_DIR] [--online] [--max-lines N]

Errors (exit code 1): emojis, long dashes or a hyphen used as one, missing
language switch, broken local links/images/anchors, leftover placeholders,
"generated by AI" mentions, README over the hard line limit, and with
--online, badges that fail to render.
Warnings: README length outside the target range, AI-sounding wording,
EN/FR structure mismatch, missing license/version badge, heavy images,
badge logos that do not resolve.
"""
import re
import sys
import urllib.request
from pathlib import Path

TARGET_MIN, TARGET_MAX, HARD_MAX = 100, 200, 240

EMOJI_RE = re.compile(
    "["
    "\U0001F000-\U0001FAFF"  # pictographs, emoticons, transport, flags, symbols & pictographs ext.
    "☀-➿"          # misc symbols and dingbats (includes the check and cross marks)
    "⬅-⬇⬛⬜⭐⭕"
    "⌚⌛⏩-⏺▶◀◻-◾⤴⤵〰〽㊗㊙"
    "️‍⃣"     # emoji presentation selector, zero-width joiner, keycap
    "]"
)
LONG_DASH_RE = re.compile("[—–―‒]")
HYPHEN_AS_DASH_RE = re.compile(r"(?<=\S) -{1,2} (?=\S)")

AI_TELLS = [
    # English
    "seamless", "seamlessly", "leverage", "leveraging", "cutting-edge", "game-changer", "game changer",
    "unlock the", "unleash", "empower", "elevate your", "delve", "dive into", "dive in", "harness the power",
    "in today's", "whether you're", "whether you are", "look no further", "streamline", "effortless",
    "effortlessly", "next-level", "revolutionize", "revolutionary", "supercharge", "blazing fast",
    "blazingly", "robust and", "state-of-the-art", "a testament to", "it's not just", "is not just a",
    "embark", "journey", "elevate", "world-class", "best-in-class", "magic happens", "happy coding",
    "boasts", "a breeze", "tailored to your needs", "all-in-one solution", "comprehensive solution",
    # French
    "révolutionnaire", "révolutionne", "sans effort", "en toute simplicité", "n'attendez plus",
    "plongez", "boostez", "booster votre", "de pointe", "incontournable", "un jeu d'enfant",
    "que vous soyez", "libérez", "sublimez", "à portée de main", "véritable allié", "en un clin d'oeil",
    "en un clin d'œil", "fluide et intuitive", "fluide et intuitif", "bon code", "propulsé par",
]
PLACEHOLDERS = re.compile(r"\b(TODO|TBD|FIXME|XXX|lorem ipsum|USER/REPO|OWNER/REPO|your-username|"
                          r"<your[-_ ][a-z-]+>|<project[-_ ]name>)\b", re.I)
AI_MENTION = re.compile(r"(generated (by|with) (ai|claude|chatgpt|an ai)|written by (ai|claude|chatgpt)|"
                        r"généré (par|avec) (l'?ia|une ia|claude|chatgpt)|rédigé par (l'?ia|une ia|claude))", re.I)

LINK_RE = re.compile(r"!?\[(?:[^\]\[]|\[[^\]]*\])*\]\(\s*<?([^)\s>]+)>?(?:\s+\"[^\"]*\")?\s*\)")
HTML_ATTR_RE = re.compile(r"\b(?:href|src|srcset)\s*=\s*\"([^\"]+)\"", re.I)
HEADING_RE = re.compile(r"^(#{1,6})\s+(.+?)\s*#*\s*$")
EXPLICIT_ANCHOR_RE = re.compile(r"<a\s+(?:id|name)\s*=\s*\"([^\"]+)\"", re.I)
BADGE_HOSTS = ("img.shields.io", "badge.svg", "vsmarketplacebadges", "badgen.net", "badge.fury.io")


class Report:
    def __init__(self):
        self.errors, self.warnings = [], []

    def err(self, f, line, msg):
        self.errors.append(f"{f}:{line}: {msg}")

    def warn(self, f, line, msg):
        self.warnings.append(f"{f}:{line}: {msg}")


def split_code(text):
    """Return (prose_lines, code_lines): same length as the file, with the other kind blanked."""
    prose, code, fence = [], [], None
    for line in text.splitlines():
        stripped = line.lstrip()
        m = re.match(r"^(`{3,}|~{3,})", stripped)
        if fence is None and m:
            fence = m.group(1)[0] * len(m.group(1))
            prose.append("")
            code.append(line)
            continue
        if fence is not None:
            if stripped.startswith(fence):
                fence = None
            prose.append("")
            code.append(line)
            continue
        prose.append(line)
        code.append("")
    return prose, code


def strip_inline(line):
    """Remove inline code, URLs and HTML attribute values so they are not linted as prose."""
    line = re.sub(r"`[^`]*`", "", line)
    line = re.sub(r"\]\([^)]*\)", "]", line)
    line = re.sub(r"\b(href|src|srcset|width|height|align|id|name|style)\s*=\s*\"[^\"]*\"", "", line)
    line = re.sub(r"https?://\S+", "", line)
    line = re.sub(r"<!--.*?-->", "", line)
    return line


def github_slug(text):
    text = re.sub(r"!\[[^\]]*\]\([^)]*\)", "", text)           # images
    text = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", text)        # links -> text
    text = re.sub(r"<[^>]+>", "", text)                          # html tags
    text = text.replace("`", "").replace("*", "").strip().lower()
    text = re.sub(r"[^\w\- ]", "", text)
    return text.replace(" ", "-")


def collect_anchors(prose):
    anchors, seen = set(), {}
    for line in prose:
        m = HEADING_RE.match(line)
        if m:
            slug = github_slug(m.group(2))
            n = seen.get(slug, 0)
            anchors.add(slug if n == 0 else f"{slug}-{n}")
            seen[slug] = n + 1
        for a in EXPLICIT_ANCHOR_RE.findall(line):
            anchors.add(a)
            anchors.add(a.lower())
    return anchors


def links_in(lines):
    for i, line in enumerate(lines, 1):
        for m in LINK_RE.finditer(line):
            yield i, m.group(1)
        for m in HTML_ATTR_RE.finditer(line):
            for part in m.group(1).split(","):
                yield i, part.strip().split(" ")[0]


def check_file(path, rep, kind, max_lines):
    name = path.name
    text = path.read_text(encoding="utf-8")
    lines = text.splitlines()
    prose, code = split_code(text)

    for i, raw in enumerate(prose, 1):
        line = strip_inline(raw)
        found = [c for c in dict.fromkeys(EMOJI_RE.findall(raw)) if c not in "️‍⃣"]
        if found or EMOJI_RE.search(raw):
            shown = " ".join(found) or "invisible emoji modifier"
            rep.err(name, i, f"emoji {shown}: replace with words (Yes/No in tables)")
        if LONG_DASH_RE.search(line):
            rep.err(name, i, "long dash (— or –): rewrite with a comma, colon, parentheses or two "
                             "sentences; for ranges write 'to' ('20 to 30 min')")
        if not re.match(r"^\s*\|?\s*:?-{3,}", line) and HYPHEN_AS_DASH_RE.search(line):
            rep.err(name, i, "hyphen used as a dash (' - '): rewrite the sentence")
        low = line.lower()
        for tell in AI_TELLS:
            if re.search(rf"(?<![\w']){re.escape(tell)}(?![\w])", low):
                rep.warn(name, i, f"AI-sounding wording: {tell!r}")
        if PLACEHOLDERS.search(line):
            rep.err(name, i, f"placeholder left: {PLACEHOLDERS.search(line).group(0)!r}")
        if AI_MENTION.search(line):
            rep.err(name, i, "mentions the text was generated by AI")
    for i, raw in enumerate(code, 1):
        if EMOJI_RE.search(raw):
            rep.warn(name, i, "emoji inside a code block: keep only if it is real program output")

    # local links, images and anchors
    anchors = collect_anchors(prose)
    for i, target in links_in(prose):
        if re.match(r"^[a-z][a-z0-9+.-]*:", target, re.I) or target.startswith("//"):
            continue
        if target.startswith("#"):
            if target[1:] and target[1:] not in anchors and target[1:].lower() not in anchors:
                rep.err(name, i, f"anchor {target} matches no heading in this file")
            continue
        local = target.split("#")[0].split("?")[0]
        if local and not (path.parent / local).exists():
            rep.err(name, i, f"missing local file: {local}")
        elif local and Path(local).suffix.lower() in {".png", ".jpg", ".jpeg", ".gif", ".webp"}:
            size_mb = (path.parent / local).stat().st_size / 1_048_576
            if size_mb > 8:
                rep.err(name, i, f"{local} weighs {size_mb:.1f} MB: GitHub may not render it, shrink it")
            elif size_mb > 4:
                rep.warn(name, i, f"{local} weighs {size_mb:.1f} MB: consider shrinking it")

    if kind in ("en", "fr"):
        n = len(lines)
        if n > max_lines:
            rep.err(name, n, f"{n} lines, over the hard limit of {max_lines}: move detail to <details> or docs/")
        elif n > TARGET_MAX or n < TARGET_MIN * 0.6:
            rep.warn(name, n, f"{n} lines, target is {TARGET_MIN} to {TARGET_MAX}")
        head = "\n".join(lines[:6])
        other = "README.fr.md" if kind == "en" else "README.md"
        if not re.search(rf"href=\"(\./)?{re.escape(other)}\"|\]\((\./)?{re.escape(other)}\)", head):
            rep.err(name, 1, f"no language switch to {other} in the first lines")
        badges = [u for _, u in links_in(lines[:45]) if any(h in u for h in BADGE_HOSTS)]
        if len(badges) < 2:
            rep.err(name, 1, "fewer than 2 badges at the top")
        if (path.parent / "LICENSE").exists() and not re.search(r"licen[cs]e", " ".join(badges), re.I):
            rep.warn(name, 1, "no license badge although LICENSE exists")
        if not re.search(r"version|/v/|release|/tag|pypi/v|npm/v|pub/v|marketplace", " ".join(badges), re.I):
            rep.warn(name, 1, "no version badge")
        if not re.search(r"<img|!\[", "\n".join(prose)):
            rep.warn(name, 1, "no image at all: add a screenshot, GIF or diagram")
    return {
        "h2": [l for l in prose if l.startswith("## ")],
        "images": sorted({t for _, t in links_in(prose)
                          if Path(t.split("?")[0]).suffix.lower() in {".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg"}
                          and not t.startswith("http")}),
        "badges": [u for _, u in links_in(lines[:45]) if any(h in u for h in BADGE_HOSTS)],
    }


def check_badges_online(name, urls, rep):
    bad_words = ("invalid", "not found", "inaccessible", "no releases", "no tags", "unknown",
                 "repo not found", "resource not found", "not specified", "error")
    for url in dict.fromkeys(urls):
        if not url.startswith("http"):
            continue
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "readme-forge-lint"})
            with urllib.request.urlopen(req, timeout=15) as r:
                body = r.read().decode("utf-8", "replace")
        except Exception as e:  # noqa: BLE001
            rep.err(name, 1, f"badge does not load ({e}): {url}")
            continue
        title = re.search(r"<title>([^<]*)</title>", body)
        label = (title.group(1) if title else "").lower()
        if any(w in label for w in bad_words):
            rep.err(name, 1, f"badge renders {label!r}: {url}")
        if "logo=" in url and "<image" not in body:
            rep.warn(name, 1, f"logo slug not found by shields (badge has no icon): {url}")


def main():
    argv = sys.argv[1:]
    online = "--online" in argv
    max_lines = HARD_MAX
    if "--max-lines" in argv:
        max_lines = int(argv[argv.index("--max-lines") + 1])
    pos = [a for i, a in enumerate(argv) if not a.startswith("--") and (i == 0 or argv[i - 1] != "--max-lines")]
    root = Path(pos[0] if pos else ".").resolve()
    rep = Report()
    files = {"en": root / "README.md", "fr": root / "README.fr.md",
             "contrib": root / "CONTRIBUTING.md", "security": root / "SECURITY.md"}
    results = {}
    for kind, path in files.items():
        if path.exists():
            results[kind] = check_file(path, rep, kind, max_lines)
        elif kind in ("en", "fr"):
            rep.err(path.name, 0, "file is missing")
    if not (root / "LICENSE").exists():
        rep.err("LICENSE", 0, "file is missing")

    if "en" in results and "fr" in results:
        en, fr = results["en"], results["fr"]
        if len(en["h2"]) != len(fr["h2"]):
            rep.warn("README.fr.md", 0, f"{len(fr['h2'])} H2 sections vs {len(en['h2'])} in README.md")
        def unlocalized(paths):  # home.fr.png counts as the French twin of home.png
            return {re.sub(r"\.fr(\.[a-z0-9]+)$", r"\1", p) for p in paths}
        if unlocalized(en["images"]) != unlocalized(fr["images"]):
            only_en = unlocalized(en["images"]) - unlocalized(fr["images"])
            only_fr = unlocalized(fr["images"]) - unlocalized(en["images"])
            rep.warn("README.fr.md", 0, f"images differ from README.md (only EN: {sorted(only_en)}, only FR: {sorted(only_fr)})")
        if len(en["badges"]) != len(fr["badges"]):
            rep.warn("README.fr.md", 0, f"{len(fr['badges'])} badges vs {len(en['badges'])} in README.md")
    if online:
        for kind in ("en", "fr"):
            if kind in results:
                check_badges_online(files[kind].name, results[kind]["badges"], rep)

    for e in rep.errors:
        print(f"ERROR   {e}")
    for w in rep.warnings:
        print(f"warning {w}")
    for kind in ("en", "fr"):
        if files[kind].exists():
            print(f"{files[kind].name}: {len(files[kind].read_text(encoding='utf-8').splitlines())} lines")
    print(f"\n{len(rep.errors)} error(s), {len(rep.warnings)} warning(s)")
    sys.exit(1 if rep.errors else 0)


if __name__ == "__main__":
    main()
